SELECT * FROM (SELECT status, CASE WHEN amount >= 1610 THEN 'high' WHEN amount >= 440 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(discount) - MIN(discount) AS discount_range, MAX(order_date) AS last_order_date FROM orders GROUP BY status, CASE WHEN amount >= 1610 THEN 'high' WHEN amount >= 440 THEN 'mid' ELSE 'low' END) AS agg WHERE discount_range > 61 ORDER BY status, amount_bucket LIMIT 10
